#include "ENGINE/Source/Event/observer.h"
#include <algorithm>
#include <unordered_map>
#include <vector>

EventReg::EventReg()=default;EventReg::~EventReg()=default;
void EventReg::RegisterCallback(EventHandler f,void*p){if(!f)return;auto i=std::find_if(callbackList.begin(),callbackList.end(),[&](auto&r){return r.callback==f;});if(i==callbackList.end())callbackList.push_back({f,p});else i->param=p;}void EventReg::RegisterEvent(int id,CObserver*o){if(!o)return;auto i=std::find_if(dispatchList.begin(),dispatchList.end(),[&](auto&r){return r.pObserver==o;});if(i==dispatchList.end())dispatchList.push_back({o,id});else i->expectedEventId=id;}
void EventReg::UnregisterCallback(EventHandler f){for(auto i=callbackList.begin();i!=callbackList.end();){if(!f||i->callback==f){if((flags&0x0fffffffu)!=0){i->callback=nullptr;i->param=nullptr;flags|=0x80000000u;++i;}else i=callbackList.erase(i);if(f)break;}else++i;}}void EventReg::UnregisterEvent(CObserver*o){for(auto i=dispatchList.begin();i!=dispatchList.end();){if(!o||i->pObserver==o){if((flags&0x0fffffffu)!=0){i->pObserver=nullptr;i->expectedEventId=-1;flags|=0x80000000u;++i;}else i=dispatchList.erase(i);if(o)break;}else++i;}}
void EventReg::CleanupCallbacks(){std::erase_if(callbackList,[](auto&r){return!r.callback;});}void EventReg::CleanupEvents(){std::erase_if(dispatchList,[](auto&r){return!r.pObserver;});}int EventReg::IsCallbackRegistered(EventHandler f)const{return std::any_of(callbackList.begin(),callbackList.end(),[&](auto&r){return r.callback==f;});}int EventReg::IsEventRegistered(CObserver*o)const{return std::any_of(dispatchList.begin(),dispatchList.end(),[&](auto&r){return r.pObserver==o;});}
int EventReg::DispatchCallback(CEvent*e){++flags;std::vector<EVENTCALLBACKREG*> snapshot;for(auto&r:callbackList)snapshot.push_back(&r);int result=0;for(auto*r:snapshot)if(r->callback&&r->callback(e,r->param))result=1;--flags;if((flags&0x0fffffffu)==0&&(flags&0x80000000u)){CleanupCallbacks();CleanupEvents();flags&=~0x80000000u;}return result;}int EventReg::DispatchEvent(CEvent*e){++flags;std::vector<EVENTDISPATCHREG*>snapshot;for(auto&r:dispatchList)snapshot.push_back(&r);int result=0;for(auto*r:snapshot)if(r->pObserver){if(e)e->id=static_cast<unsigned>(r->expectedEventId);if(r->pObserver->OnEvent(e))result=1;}--flags;if((flags&0x0fffffffu)==0&&(flags&0x80000000u)){CleanupCallbacks();CleanupEvents();flags&=~0x80000000u;}return result;}
EventReg*EventRegistry::InternalNew(unsigned id){auto&entry=m_regs[id];if(!entry)entry=std::make_unique<EventReg>();return entry.get();}void EventRegistry::InternalDelete(EventReg*r){for(auto i=m_regs.begin();i!=m_regs.end();++i)if(i->second.get()==r){m_regs.erase(i);return;}}EventReg*EventRegistry::Find(unsigned id){auto i=m_regs.find(id);return i==m_regs.end()?nullptr:i->second.get();}
void ObserverInitialize(){}void ObserverDestroy(){}
CObserver::CObserver()=default;CObserver::~CObserver(){ClearRegistry();}int CObserver::OnEvent(const CEvent*){return 0;}void CObserver::ClearRegistry(){m_registry.reset();}EventRegistry*CObserver::GetRegistry(int c){if(!m_registry&&c)m_registry=std::make_unique<EventRegistry>();return m_registry.get();}EventReg*CObserver::GetEventReg(unsigned id,int c){auto*r=GetRegistry(c);return r?(c?r->InternalNew(id):r->Find(id)):nullptr;}
int CObserver::DispatchEvent(CEvent*e){return e?DispatchEvent(e->id,e):0;}int CObserver::DispatchEvent(unsigned id,CEvent*e){auto*r=GetEventReg(id,0);return r?(r->DispatchCallback(e)|r->DispatchEvent(e)):0;}
void CObserver::RegisterCallback(unsigned id,EventHandler f,void*p){if(auto*r=GetEventReg(id,1))r->RegisterCallback(f,p);}void CObserver::RegisterEvent(unsigned id,int expected,CObserver*o){if(auto*r=GetEventReg(id,1))r->RegisterEvent(expected,o);}void CObserver::UnregisterCallback(unsigned id,EventHandler f){if(auto*r=GetEventReg(id,0))r->UnregisterCallback(f);}void CObserver::UnregisterEvent(unsigned id,CObserver*o){if(auto*r=GetEventReg(id,0))r->UnregisterEvent(o);}int CObserver::IsEventRegistered(unsigned id){auto*r=GetEventReg(id,0);return r&&(!r->callbackList.empty()||!r->dispatchList.empty());}EventReg*CObserver::IsEventRegisteredBy(unsigned id,CObserver*o){auto*r=GetEventReg(id,0);return r&&r->IsEventRegistered(o)?r:nullptr;}
